"use client"

import * as React from "react"

import { useComposedRefs } from "@/lib/0nlytype/refs"
import { cn } from "@/lib/utils"

type Variant = "pizzicato" | "rubric" | "watermark" | "register"
type PicksContextValue = { name: string; value: string | undefined; select: (value: string) => void }

const PicksContext = React.createContext<PicksContextValue | null>(null)

type PicksProps = Omit<React.ComponentProps<"fieldset">, "defaultValue" | "onChange"> & {
  /** How the choice is marked. pizzicato: a dot in the margin that slides to the pick and plucks a string; rubric: the chosen title's initial hangs in the margin two lines deep, in the italic and the accent; watermark: the chosen title lies huge and faint behind the list; register: two registration crosses mark the chosen pick's corners and turn as they travel. */
  variant?: Variant
  /** Shared by every radio, so a form submits the choice. Defaults to a generated name. */
  name?: string
  /** The small label over the list. Without one, give the group an aria-label. */
  legend?: React.ReactNode
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
}

/**
 * A list of choices that carry their own content. The chosen title turns italic, because it's yours now.
 * Pizzicato hangs one accent dot beside it; choosing another slides the dot along a string that rings and falls silent.
 * Rubric hangs the chosen title's initial in the margin, two lines deep, like a rubricated capital.
 * Watermark lays the chosen title behind the list, huge and faint, as a sheet shows its mark held to the light.
 * Register marks the chosen pick's two far corners with the printer's registration crosses.
 */
function Picks({ variant = "pizzicato", name, legend, value: controlled, defaultValue, onValueChange, className, children, ref: forwardedRef, ...props }: PicksProps) {
  const generated = React.useId()
  const [uncontrolled, setUncontrolled] = React.useState(defaultValue)
  const value = controlled ?? uncontrolled
  const box = React.useRef<HTMLFieldSetElement>(null)
  const composedRef = useComposedRefs(box, forwardedRef)
  const was = React.useRef(value)
  const turn = React.useRef(0) // register: quarter turns the crosses have made
  const plucked = variant === "pizzicato"
  const measured = plucked || variant === "register"

  const select = React.useCallback(
    (next: string) => {
      if (controlled === undefined) setUncontrolled(next)
      onValueChange?.(next)
    },
    [controlled, onValueChange],
  )
  const ctx = React.useMemo(() => ({ name: name ?? generated, value, select }), [name, generated, value, select])

  // The string runs the length of the picks; the dot hangs where the chosen pick's ring would (its ::before sets the height).
  const place = React.useCallback(() => {
    const el = box.current
    const picks = el ? [...el.querySelectorAll<HTMLElement>(":scope > label")] : []
    if (el && variant === "register") return register(el, picks, turn)
    const string = el?.querySelector<HTMLElement>(":scope > .ot-picks-string")
    if (!el || !string || !picks.length) return
    // A fieldset starts its positioned children below the legend and offsetTop can't be trusted inside one, so measure
    // everything from where the string's own top: 0 would be (the string has no transform, unlike the dot).
    el.setAttribute("data-placed", "")
    const origin = string.getBoundingClientRect().top - (parseFloat(getComputedStyle(string).top) || 0)
    const at = (l: HTMLElement) => l.getBoundingClientRect().top - origin
    const first = at(picks[0])
    const last = picks[picks.length - 1]
    el.style.setProperty("--ot-picks-top", `${first}px`)
    el.style.setProperty("--ot-picks-len", `${at(last) + last.offsetHeight - first}px`)
    const chosen = picks.find((l) => l.querySelector("input:checked"))
    if (chosen) el.style.setProperty("--ot-picks-y", `${at(chosen) + (parseFloat(getComputedStyle(chosen, "::before").top) || 0)}px`)
  }, [variant])

  React.useLayoutEffect(() => {
    const el = box.current
    const from = was.current
    was.current = value
    if (!el || !measured) return
    // The dot glides only from an earlier choice; a first choice is plucked where it lands.
    if (from !== undefined && from !== value) el.setAttribute("data-ready", "")
    place()
    if (from === value || value === undefined || !plucked) return
    // Restart the pluck: the CSS animation runs again only if the attribute comes back after a style flush.
    el.removeAttribute("data-plucked")
    void el.offsetWidth
    el.setAttribute("data-plucked", "")
  }, [value, plucked, measured, place])

  // Picks re-flow on resize and when the fonts arrive; the dot and the string follow.
  // ponytail: watches the picks present at mount; add a MutationObserver if picks come and go.
  React.useEffect(() => {
    const el = box.current
    if (!el || !measured) return
    // A re-flow moves the marks without travel.
    const settle = () => {
      el.setAttribute("data-still", "")
      place()
      void el.offsetWidth
      el.removeAttribute("data-still")
    }
    const ro = new ResizeObserver(settle)
    ro.observe(el)
    el.querySelectorAll(":scope > label").forEach((l) => ro.observe(l))
    document.fonts?.ready.then(settle)
    return () => ro.disconnect()
  }, [measured, place])

  return (
    <PicksContext.Provider value={ctx}>
      <fieldset ref={composedRef} data-slot="picks" data-variant={variant} className={cn("ot-picks", className)} {...props}>
        {legend ? <legend className="ot-label">{legend}</legend> : null}
        {children}
        {plucked ? (
          <>
            <span data-slot="picks-string" className="ot-picks-string" aria-hidden="true" />
            <span data-slot="picks-dot" className="ot-picks-dot" aria-hidden="true" />
          </>
        ) : null}
        {variant === "register" ? (
          <>
            <span className="ot-picks-origin" aria-hidden="true" />
            <span data-slot="picks-cross" className="ot-picks-cross" data-corner="start" aria-hidden="true" />
            <span data-slot="picks-cross" className="ot-picks-cross" data-corner="end" aria-hidden="true" />
          </>
        ) : null}
      </fieldset>
    </PicksContext.Provider>
  )
}

// Register: a cross stands off each of the chosen pick's two far corners (the top of its start side, the foot of its end
// side), by --ot-picks-out. Physical px from the origin, a zero box at the fieldset's top left, so direction only
// decides which corners. Each move turns the crosses a quarter, the way the pick went.
function register(el: HTMLElement, picks: HTMLElement[], turn: React.RefObject<number>) {
  const chosen = picks.find((l) => l.querySelector("input:checked"))
  const origin = el.querySelector(":scope > .ot-picks-origin")?.getBoundingClientRect()
  if (!chosen || !origin) return
  el.setAttribute("data-placed", "")
  const k = el.getBoundingClientRect().width / (el.offsetWidth || 1) || 1 // a zoomed preview
  const r = chosen.getBoundingClientRect()
  const out = parseFloat(getComputedStyle(el).getPropertyValue("--ot-picks-out")) || 12
  const rtl = getComputedStyle(chosen).direction === "rtl"
  const [left, right] = [(r.left - origin.left) / k - out, (r.right - origin.left) / k + out]
  const [top, foot] = [(r.top - origin.top) / k - out, (r.bottom - origin.top) / k + out]
  const was = parseFloat(el.style.getPropertyValue("--ot-picks-y0"))
  if (el.hasAttribute("data-ready") && !el.hasAttribute("data-still") && Number.isFinite(was) && Math.abs(top - was) > 1) turn.current += top > was ? 90 : -90
  const set = (p: string, v: number, u = "px") => el.style.setProperty(`--ot-picks-${p}`, `${v}${u}`)
  set("x0", rtl ? right : left)
  set("y0", top)
  set("x1", rtl ? left : right)
  set("y1", foot)
  set("turn", turn.current, "deg")
}

type PickProps = Omit<React.ComponentProps<"input">, "type" | "name" | "checked" | "defaultChecked" | "value" | "children"> & {
  value: string
  /** Anything: a PickTitle and a PickDescription, a swatch, a specimen. Plain text is taken as the title. */
  children: React.ReactNode
  /** Classes for the label, which is the root. className goes to the input. */
  labelClassName?: string
  /** Pins a state for documentation ("hover", "focus"); set on the root. */
  "data-force"?: string
}

function Pick({ value, children, className, labelClassName, "data-force": force, onChange, ...props }: PickProps) {
  const group = React.useContext(PicksContext)
  if (!group) throw new Error("Pick must sit inside <Picks>.")
  return (
    <label data-slot="pick" data-force={force} className={labelClassName}>
      <input
        type="radio"
        name={group.name}
        value={value}
        checked={group.value === value}
        className={className}
        onChange={(e) => {
          onChange?.(e)
          group.select(value)
        }}
        {...props}
      />
      {typeof children === "string" ? <PickTitle>{children}</PickTitle> : children}
    </label>
  )
}

type PickTitleProps = React.ComponentProps<"span"> & {
  /** The pick's name. Plain text turns italic when chosen, and its initial is the one rubric hangs (a name without capitals gets a pilcrow instead). */
  children: React.ReactNode
}

/** The pick's name. Set in the voice; the chosen one crosses into the italic. */
function PickTitle({ className, children, ...props }: PickTitleProps) {
  if (typeof children !== "string") {
    return <span data-slot="pick-title" className={cn("ot-pick-title", className)} {...props}>{children}</span>
  }
  // The first letter (a whole grapheme) is its own span so rubric can hang it, and the rest its own so it can turn
  // italic beside it. data-initial feeds the ghost that holds the letter's place. Readers get the name whole.
  const first = new Intl.Segmenter().segment(children)[Symbol.iterator]().next().value?.segment ?? ""
  // A script without capitals (Arabic, Hebrew, Devanagari, Han), or a name that opens on a figure or a mark, has no
  // initial to hang, and lifting one out would break a joined word. Rubric paints the rubricator's other mark there,
  // the pilcrow, and leaves the name whole.
  if (first.toLocaleUpperCase() === first.toLocaleLowerCase()) {
    return (
      <span data-slot="pick-title" data-text={children} data-caseless="" className={cn("ot-pick-title", className)} {...props}>
        <span aria-hidden="true" data-initial="">
          <span className="ot-pick-initial" data-text={"\u00b6"}>
            <span />
          </span>
          <span className="ot-pick-rest" data-text={children}>
            <span>{children}</span>
          </span>
        </span>
        <span className="ot-sr">{children}</span>
      </span>
    )
  }
  const rest = children.slice(first.length)
  return (
    <span data-slot="pick-title" data-text={children} className={cn("ot-pick-title", className)} {...props}>
      <span aria-hidden="true" data-initial={first}>
        <span className="ot-pick-initial" data-text={first}><span>{first}</span></span>
        <span className="ot-pick-rest" data-text={rest}><span>{rest}</span></span>
      </span>
      <span className="ot-sr">{children}</span>
    </span>
  )
}

/** A line under the title, in the pencil. */
function PickDescription({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="pick-description" className={cn("ot-pick-description", className)} {...props} />
}

export { Picks, Pick, PickTitle, PickDescription, type PicksProps, type PickProps, type PickTitleProps }

@layer components {
  /* ── ot-picks ── choices that carry their own content. The chosen title crosses into the italic, because it's yours.
     Two ways to mark it: pizzicato hangs one accent dot in the margin, and rubric hangs the chosen initial in the margin, two lines deep. */
  @property --ot-picks-y { syntax: "<length>"; inherits: true; initial-value: 0px; }
  @property --ot-picks-d { syntax: "<length>"; inherits: true; initial-value: 0px; }
  .ot-picks {
    --ot-picks-y: 0px;   /* the dot's top; script sets it from the chosen pick */
    --ot-picks-d: 0px;   /* how far the string is pulled toward the words; the pluck animates it */
    --ot-picks-top: 0px; /* where the string starts (the first pick's top) */
    --ot-picks-len: 0px; /* and how long it runs (to the last pick's foot) */
    --dir: 1;
    position: relative; border: 0; margin: 0; padding: 0; min-width: 0;
    display: grid; justify-items: start; gap: var(--ot-space-5);
  }
  .ot-picks:is([dir="rtl"], [dir="rtl"] *) { --dir: -1; }
  /* A pick written in the other direction carries its own dir; the nearest one sets which way things hang. */
  .ot-picks [dir="ltr"] { --dir: 1; }
  .ot-picks [dir="rtl"] { --dir: -1; }
  .ot-picks > legend { padding: 0; margin-bottom: var(--ot-space-4); }
  .ot-picks > label {
    position: relative; display: block; max-width: 100%; cursor: pointer;
    font-size: var(--ot-mp); line-height: var(--ot-mp-lh); letter-spacing: var(--ot-mp-tr);
    color: var(--ot-graphite); -webkit-tap-highlight-color: transparent;
    transition: color var(--ot-allegro);
  }
  .ot-picks > label > input { position: absolute; width: 1px; height: 1px; margin: 0; opacity: 0; pointer-events: none; }
  .ot-picks > label:is(:hover, [data-force~="hover"], :has(input:checked)):not(:has(input:disabled)) { color: var(--ot-ink); }
  .ot-picks > label:is(:has(input:focus-visible), [data-force~="focus"]) { outline: var(--ot-stroke) solid var(--ot-accent); outline-offset: 6px; }
  .ot-picks > label:has(input:disabled) { color: var(--ot-pencil); opacity: 0.55; cursor: not-allowed; }

  /* The title. Plain text carries an italic copy in the same grid cell, so the two cross-fade without moving anything. */
  .ot-pick-title { display: grid; justify-items: start; align-items: baseline; }
  .ot-pick-title > [aria-hidden],
  .ot-pick-title[data-text]::after {
    grid-area: 1 / 1;
    transition: opacity var(--ot-moderato) var(--ot-breath), translate var(--ot-moderato) var(--ot-exhale);
  }
  .ot-pick-title[data-text]::after {
    content: attr(data-text) / "";
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1; letter-spacing: 0;
    opacity: 0; translate: 0 0.12em;
  }
  .ot-pick-description {
    display: block; max-width: 44ch;
    font-size: var(--ot-p); line-height: var(--ot-p-lh); letter-spacing: var(--ot-p-tr);
    color: var(--ot-pencil); transition: color var(--ot-allegro);
  }
  .ot-picks > label:has(input:checked) .ot-pick-description { color: var(--ot-graphite); }

  /* pizzicato: the dot hangs in the margin. Pointing sketches a ring where it would land (and a press tightens it, a finger
     on the string). Choosing slides the dot there along a hairline string, pulling it aside as it goes; on arrival the
     string is let go and rings, and fades back to silence as it settles. The title turns italic as the dot lands. */
  .ot-picks[data-variant="pizzicato"] > label { margin-inline-start: var(--ot-space-5); }
  .ot-picks[data-variant="pizzicato"] > label::before {
    content: ""; position: absolute; inset-inline-start: calc(-1 * var(--ot-space-5)); top: calc(0.5lh + 0.03em - var(--ot-dot) / 2);
    width: var(--ot-dot); height: var(--ot-dot); border-radius: 50%;
    box-shadow: inset 0 0 0 var(--ot-hairline) var(--ot-rule-strong); scale: 0; pointer-events: none;
    transition: scale var(--ot-moderato) var(--ot-spiccato);
  }
  .ot-picks[data-variant="pizzicato"] > label:is(:hover, [data-force~="hover"]):not(:has(input:checked, input:disabled))::before { scale: 1; }
  .ot-picks[data-variant="pizzicato"] > label:active:not(:has(input:checked, input:disabled))::before { scale: 0.6; transition-duration: var(--ot-allegro); }
  .ot-picks:is([data-variant="pizzicato"], [data-variant="watermark"], [data-variant="register"]) > label:has(input:checked) .ot-pick-title > [aria-hidden] { opacity: 0; translate: 0 -0.12em; }
  .ot-picks:is([data-variant="pizzicato"], [data-variant="watermark"], [data-variant="register"]) > label:has(input:checked) .ot-pick-title::after { opacity: 1; translate: 0 0; }
  .ot-picks[data-variant="pizzicato"][data-ready] > label:has(input:checked) .ot-pick-title > [aria-hidden],
  .ot-picks[data-variant="pizzicato"][data-ready] > label:has(input:checked) .ot-pick-title::after { transition-delay: calc(var(--ot-moderato) * 0.7); }
  .ot-picks-dot, .ot-picks-string { position: absolute; top: 0; pointer-events: none; }
  .ot-picks-dot {
    inset-inline-start: 0; width: var(--ot-dot); height: var(--ot-dot); border-radius: 50%; background: var(--ot-accent);
    translate: calc(var(--ot-picks-d) * var(--dir)) var(--ot-picks-y);
    transition: opacity var(--ot-allegro), scale var(--ot-moderato) var(--ot-spiccato);
  }
  .ot-picks:not(:has(input:checked)) > .ot-picks-dot { opacity: 0; scale: 0; }
  /* Until script has measured (before hydration, or without script), the chosen pick's own ring stands in for the dot. */
  .ot-picks:not([data-placed]) > :is(.ot-picks-dot, .ot-picks-string) { display: none; }
  .ot-picks[data-variant="pizzicato"]:not([data-placed]) > label:has(input:checked)::before { scale: 1; background: var(--ot-accent); box-shadow: none; }
  /* The string is a hairline bent at the dot: a thin strip clipped out of a wider box, so it stays one hairline at any pull. */
  .ot-picks-string {
    --apex: calc(var(--ot-picks-y) + var(--ot-dot) / 2 - var(--ot-picks-top));
    --x: calc(var(--ot-picks-d) * var(--dir));
    top: var(--ot-picks-top); height: var(--ot-picks-len); inset-inline-start: calc(var(--ot-dot) / 2 - 1em); width: 2em;
    background: var(--ot-rule-strong); opacity: 0;
    clip-path: polygon(
      calc(50% - 0.5px) 0, calc(50% - 0.5px + var(--x)) var(--apex), calc(50% - 0.5px) 100%,
      calc(50% + 0.5px) 100%, calc(50% + 0.5px + var(--x)) var(--apex), calc(50% + 0.5px) 0
    );
  }
  .ot-picks[data-ready] { transition: --ot-picks-y var(--ot-moderato) var(--ot-breath); }
  .ot-picks[data-plucked] { animation: ot-picks-pluck calc(var(--ot-moderato) + var(--ot-andante)) linear; }
  .ot-picks[data-plucked] > .ot-picks-string { animation: ot-picks-ring calc(var(--ot-moderato) + var(--ot-andante)) linear; }
  /* A third of the time the pull (while the dot slides), then five half-swings, each smaller, each eased like a pendulum. */
  @keyframes ot-picks-pluck {
    0% { --ot-picks-d: 0px; animation-timing-function: var(--ot-breath); }
    33% { --ot-picks-d: -0.45em; animation-timing-function: var(--ot-breath); }
    47% { --ot-picks-d: 0.3em; animation-timing-function: var(--ot-breath); }
    60% { --ot-picks-d: -0.18em; animation-timing-function: var(--ot-breath); }
    73% { --ot-picks-d: 0.1em; animation-timing-function: var(--ot-breath); }
    86% { --ot-picks-d: -0.04em; animation-timing-function: var(--ot-breath); }
    100% { --ot-picks-d: 0px; }
  }
  @keyframes ot-picks-ring {
    0% { opacity: 0; }
    14%, 33% { opacity: 1; }
    100% { opacity: 0; }
  }

  /* rubric: the chosen title's initial is lifted out of the word and hung in the margin as a two-line capital, in the
     italic and the accent, the way a rubricator painted the one red letter a section began with. It hangs, so nothing
     around it reflows: every pick keeps a margin for it, the capital grows into that margin from its place in the word,
     and a ghost of the small letter narrows to nothing so the rest of the name closes up to the edge and turns italic.
     Its foot sits on the first line under the title, so a pick without a description keeps that line free.
     Pointing leans the initial italic, in place. */
  .ot-picks[data-variant="rubric"] { --ot-picks-cap: 2.3; interpolate-size: allow-keywords; }
  .ot-picks[data-variant="rubric"] > label { padding-inline-start: var(--ot-space-7); } /* inside the label, so focus and the pointer take the capital in */
  .ot-picks[data-variant="rubric"] > label:not(:has(.ot-pick-description)) { padding-block-end: calc(var(--ot-p) * var(--ot-p-lh)); }
  .ot-picks[data-variant="rubric"] .ot-pick-title { display: block; position: relative; }
  .ot-picks[data-variant="rubric"] .ot-pick-title::after { content: none; }
  /* The ghost: the small roman letter, holding the initial's place in the word until it is chosen. */
  .ot-picks[data-variant="rubric"] .ot-pick-title > [data-initial]::before {
    content: attr(data-initial) / ""; display: inline-block; width: max-content; overflow: hidden; white-space: nowrap; vertical-align: top; visibility: hidden;
    transition: width var(--ot-andante) var(--ot-exhale);
  }
  .ot-picks[data-variant="rubric"] > label:has(input:checked) .ot-pick-title > [data-initial]::before { width: 0; }
  .ot-picks[data-variant="rubric"] .ot-pick-initial {
    position: absolute; top: 0; inset-inline-start: 0; display: grid; justify-items: start; align-items: baseline;
    font-size: 1em; translate: 0 0;
    transition: font-size var(--ot-andante) var(--ot-exhale), line-height var(--ot-andante) var(--ot-exhale), translate var(--ot-andante) var(--ot-exhale), color var(--ot-moderato);
  }
  .ot-picks[data-variant="rubric"] :is(.ot-pick-initial, .ot-pick-rest) > span,
  .ot-picks[data-variant="rubric"] :is(.ot-pick-initial, .ot-pick-rest)::after { grid-area: 1 / 1; transition: opacity var(--ot-moderato) var(--ot-breath), translate var(--ot-moderato) var(--ot-exhale); }
  .ot-picks[data-variant="rubric"] :is(.ot-pick-initial, .ot-pick-rest)::after {
    content: attr(data-text) / "";
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-expression-scale) * 1em); line-height: 1; letter-spacing: 0;
    opacity: 0;
  }
  /* The rest of the name cross-fades into the italic in place, the way pizzicato's whole title does. */
  .ot-picks[data-variant="rubric"] .ot-pick-rest { display: inline-grid; justify-items: start; align-items: baseline; }
  .ot-picks[data-variant="rubric"] .ot-pick-rest::after { translate: 0 0.12em; }
  .ot-picks[data-variant="rubric"] > label:has(input:checked) .ot-pick-rest > span { opacity: 0; translate: 0 -0.12em; }
  .ot-picks[data-variant="rubric"] > label:has(input:checked) .ot-pick-rest::after { opacity: 1; translate: 0 0; }
  .ot-picks[data-variant="rubric"] > label:is(:hover, [data-force~="hover"], :has(input:checked)):not(:has(input:disabled)) .ot-pick-initial > span { opacity: 0; }
  .ot-picks[data-variant="rubric"] > label:is(:hover, [data-force~="hover"], :has(input:checked)):not(:has(input:disabled)) .ot-pick-initial::after { opacity: 1; }
  /* Hung: its own width back into the margin, plus a gap the italic's overhang can lean into. */
  .ot-picks[data-variant="rubric"] > label:has(input:checked) .ot-pick-initial {
    font-size: calc(var(--ot-picks-cap) * 1em); line-height: 1; color: var(--ot-accent);
    translate: calc(-1 * var(--dir) * (100% + 0.2em)) 0.02em;
  }

  /* A name without capitals (a script without case, or one that opens on a figure) has no initial to lift, and lifting
     one would break a joined word apart. The name stays whole and turns italic, and the rubricator's other mark, the
     pilcrow, is painted in the margin in its place: unseen until chosen, then grown into the margin the same way. */
  .ot-picks[data-variant="rubric"] [data-caseless] .ot-pick-initial { opacity: 0; transition: opacity var(--ot-allegro), font-size var(--ot-andante) var(--ot-exhale), line-height var(--ot-andante) var(--ot-exhale), translate var(--ot-andante) var(--ot-exhale), color var(--ot-moderato); }
  .ot-picks[data-variant="rubric"] [data-caseless] .ot-pick-initial::after { scale: var(--dir) 1; }
  .ot-picks[data-variant="rubric"] > label:has(input:checked) [data-caseless] .ot-pick-initial { opacity: 1; font-size: calc(var(--ot-picks-cap) * 0.8em); }

  /* A cased name on a right-to-left page (a Latin name among Arabic) begins at the end away from the page's margin, so its
     initial has nowhere to hang: lifted, the word would read "ressP". The name stays whole in its own order (an isolated
     left-to-right run), and the pilcrow hangs in the margin instead, as for a name without capitals. A pick or a title
     given dir="ltr" is a left-to-right block with its margin on the left, and hangs its capital there as usual.
     ponytail: reads direction from the dir attribute, as the rest of the library does; a dir="ltr" wrapper between the page and the picks isn't seen. */
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]) .ot-pick-title:not([data-caseless], [dir="ltr"]) > [data-initial] { direction: ltr; unicode-bidi: isolate; }
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]) .ot-pick-title:not([data-caseless], [dir="ltr"]) > [data-initial]::before { content: none; }
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]) .ot-pick-title:not([data-caseless], [dir="ltr"]) .ot-pick-initial { position: relative; display: inline-grid; }
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]) .ot-pick-title:not([data-caseless], [dir="ltr"]) .ot-pick-rest { position: relative; }
  /* Whichever face is showing sets the word's room, so it neither gaps nor stops short of the page's edge. */
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]) .ot-pick-title:not([data-caseless], [dir="ltr"]) :is(.ot-pick-initial, .ot-pick-rest)::after,
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]):has(input:checked) .ot-pick-title:not([data-caseless], [dir="ltr"]) :is(.ot-pick-initial, .ot-pick-rest) > span { position: absolute; inset-inline-start: 0; bottom: 0; white-space: nowrap; }
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]):has(input:checked) .ot-pick-title:not([data-caseless], [dir="ltr"]) :is(.ot-pick-initial, .ot-pick-rest)::after { position: static; }
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]):has(input:checked) .ot-pick-title:not([data-caseless], [dir="ltr"]) .ot-pick-initial { font-size: 1em; line-height: inherit; color: inherit; translate: none; }
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]) .ot-pick-title:not([data-caseless], [dir="ltr"])::before {
    content: "\00b6" / ""; position: absolute; top: 0; inset-inline-start: 0; pointer-events: none;
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; line-height: 1; letter-spacing: 0; color: var(--ot-accent);
    font-size: calc(var(--ot-expression-scale) * 1em); scale: -1 1; opacity: 0; translate: 0 0;
    transition: opacity var(--ot-allegro), font-size var(--ot-andante) var(--ot-exhale), translate var(--ot-andante) var(--ot-exhale);
  }
  .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]):has(input:checked) .ot-pick-title:not([data-caseless], [dir="ltr"])::before { opacity: 1; font-size: calc(var(--ot-picks-cap) * 0.8em * var(--ot-expression-scale)); translate: calc(100% + 0.2em) 0.02em; }

  /* watermark: the chosen title lies behind the list, huge and faint in the italic, set off its foot and its end edge
     and cropped by them, the way a sheet shows its mould's mark when held to the light (and the ghost numerals stand
     behind "the silence that heals"). Choosing another lets one mark fade and the next come up out of the paper;
     nothing travels. The title itself crosses into the italic, as pizzicato's does. */
  .ot-picks[data-variant="watermark"] { isolation: isolate; padding-block-end: var(--ot-space-6); }
  /* Each title carries its own mark, set against the fieldset (the picks stand unpositioned for it), so one fades
     while the next comes up. The box is shorter than the line and no wider than the list, so the list's foot and end edge crop it. */
  .ot-picks[data-variant="watermark"] > label { position: static; }
  .ot-picks[data-variant="watermark"] .ot-pick-title[data-text]::before {
    content: attr(data-text) / ""; position: absolute; inset-block-end: 0; inset-inline-end: 0; z-index: -1;
    max-inline-size: 100%; block-size: min(0.66em, 100%); overflow: hidden; pointer-events: none; user-select: none;
    font-family: var(--ot-expression); font-style: italic; font-weight: 400; font-size: calc(var(--ot-expression-scale) * var(--ot-fff));
    line-height: 0.8; letter-spacing: -0.02em; white-space: nowrap; color: color-mix(in srgb, var(--ot-ink) 8%, transparent);
    opacity: 0; translate: 0 0.06em; transition: opacity var(--ot-moderato) var(--ot-breath), translate var(--ot-moderato) var(--ot-breath);
  }
  .ot-picks[data-variant="watermark"] > label:has(input:checked) .ot-pick-title[data-text]::before {
    opacity: 1; translate: 0 0; transition: opacity var(--ot-andante) var(--ot-exhale) var(--ot-allegro), translate var(--ot-andante) var(--ot-exhale) var(--ot-allegro);
  }

  /* register: the printer's registration crosses, one off the top of the chosen pick's start side and one off the foot
     of its end side, as "the uncreative" marks its corners with two + signs. Pointing sketches the pair in pencil at
     that pick; choosing sends the accent pair there, each turning a quarter the way it goes (a cross turned a quarter
     is the same cross, so it only reads as turning while it moves), the far one a beat behind. */
  @property --ot-picks-out { syntax: "<length>"; inherits: true; initial-value: 0px; }
  .ot-picks[data-variant="register"] { --ot-picks-out: var(--ot-space-3); --ot-picks-cross: 0.62em; --ot-picks-ink: var(--ot-accent); }
  .ot-picks[data-variant="register"] > label { margin-inline: var(--ot-space-5); max-width: calc(100% - 2 * var(--ot-space-5)); }
  .ot-picks[data-variant="register"] > label::before,
  .ot-picks[data-variant="register"] > label::after,
  .ot-picks-cross {
    content: ""; position: absolute; width: var(--ot-picks-cross); height: var(--ot-picks-cross); pointer-events: none;
    background:
      linear-gradient(var(--ot-picks-ink) 0 0) center / 100% var(--ot-stroke) no-repeat,
      linear-gradient(var(--ot-picks-ink) 0 0) center / var(--ot-stroke) 100% no-repeat;
  }
  .ot-picks[data-variant="register"] > label::before,
  .ot-picks[data-variant="register"] > label::after {
    --ot-picks-ink: var(--ot-rule-strong); scale: 0; transition: scale var(--ot-allegro) var(--ot-exhale);
  }
  .ot-picks[data-variant="register"] > label::before { inset-inline-start: calc(-1 * (var(--ot-picks-out) + var(--ot-picks-cross) / 2)); top: calc(-1 * (var(--ot-picks-out) + var(--ot-picks-cross) / 2)); }
  .ot-picks[data-variant="register"] > label::after { inset-inline-end: calc(-1 * (var(--ot-picks-out) + var(--ot-picks-cross) / 2)); bottom: calc(-1 * (var(--ot-picks-out) + var(--ot-picks-cross) / 2)); }
  .ot-picks[data-variant="register"] > label:is(:hover, [data-force~="hover"]):not(:has(input:checked, input:disabled))::before,
  .ot-picks[data-variant="register"] > label:is(:hover, [data-force~="hover"]):not(:has(input:checked, input:disabled))::after { scale: 1; transition: scale var(--ot-moderato) var(--ot-spiccato); }
  /* Until script has measured, the chosen pick's own pair stands in, inked. */
  .ot-picks[data-variant="register"]:not([data-placed]) > label:has(input:checked)::before,
  .ot-picks[data-variant="register"]:not([data-placed]) > label:has(input:checked)::after { --ot-picks-ink: var(--ot-accent); scale: 1; }
  .ot-picks-origin { position: absolute; top: 0; left: 0; width: 0; height: 0; }
  .ot-picks-cross {
    top: 0; left: 0; rotate: var(--ot-picks-turn, 0deg);
    translate: calc(var(--ot-picks-x0, 0px) - 50%) calc(var(--ot-picks-y0, 0px) - 50%);
  }
  .ot-picks-cross[data-corner="end"] { translate: calc(var(--ot-picks-x1, 0px) - 50%) calc(var(--ot-picks-y1, 0px) - 50%); }
  .ot-picks:is(:not([data-placed]), :not(:has(input:checked))) > .ot-picks-cross { opacity: 0; }
  .ot-picks[data-variant="register"][data-ready]:not([data-still]) > .ot-picks-cross { transition: translate var(--ot-moderato) var(--ot-breath), rotate var(--ot-moderato) var(--ot-breath), opacity var(--ot-allegro); }
  .ot-picks[data-variant="register"][data-ready]:not([data-still]) > .ot-picks-cross[data-corner="end"] { transition-delay: calc(var(--ot-arpeggio) * 2); }

  @media (forced-colors: active) {
    .ot-picks > label:is(:has(input:focus-visible), [data-force~="focus"]) { outline-color: Highlight; }
    .ot-picks[data-variant="pizzicato"] > label::before { box-shadow: none; border: var(--ot-hairline) solid CanvasText; }
    .ot-picks-dot, .ot-picks-string { forced-color-adjust: none; }
    .ot-picks-dot { background: Highlight; }
    .ot-picks-string { background: CanvasText; }
    .ot-picks[data-variant="rubric"] > label:has(input:checked) .ot-pick-initial { forced-color-adjust: none; color: Highlight; }
    .ot-picks[data-variant="rubric"]:is([dir="rtl"], [dir="rtl"] *):not([dir="ltr"]) > label:not([dir="ltr"]):has(input:checked) .ot-pick-title:not([data-caseless], [dir="ltr"])::before { forced-color-adjust: none; color: Highlight; }
    .ot-picks[data-variant="register"] > label::before, .ot-picks[data-variant="register"] > label::after, .ot-picks-cross { forced-color-adjust: none; }
    .ot-picks[data-variant="register"] { --ot-picks-ink: Highlight; }
    .ot-picks[data-variant="watermark"] .ot-pick-title[data-text]::before { content: none; } /* no faint ink to hold to the light */
    .ot-picks[data-variant="register"] > label::before, .ot-picks[data-variant="register"] > label::after { --ot-picks-ink: CanvasText; }
    .ot-picks[data-variant="register"]:not([data-placed]) > label:has(input:checked)::before,
    .ot-picks[data-variant="register"]:not([data-placed]) > label:has(input:checked)::after { --ot-picks-ink: Highlight; }
  }
}
